/* Native test-MON reward pool. Wallet secrets never enter this application. */
window.monad=(()=>{
 const E=ethers,A=CAMPUS_POOL_ARTIFACT,CHAIN=10143,HEX='0x279f',RPC='https://testnet-rpc.monad.xyz',EXPLORER='https://testnet.monadexplorer.com';
 const reader=new E.JsonRpcProvider(RPC,CHAIN,{staticNetwork:true,batchMaxCount:1,cacheTimeout:-1});
 let injected=null,address='',pool='',snapshot=null,busy=false,message='',lastTx=null,epoch=0;
 const wallets=new Map();let saved={};try{saved=JSON.parse(localStorage.getItem('campus-monad-v1'))||{};pool=E.isAddress(saved.pool||'')?E.getAddress(saved.pool):'';lastTx=/^0x[0-9a-fA-F]{64}$/.test(saved.tx?.hash||'')?saved.tx:null;}catch{}
 const persist=()=>{try{localStorage.setItem('campus-monad-v1',JSON.stringify({pool,tx:lastTx}));}catch{}};
 const short=a=>a?a.slice(0,6)+'…'+a.slice(-4):'';
 const fmt=n=>E.formatEther(n??0n);
 const esc=s=>escapeHTML(String(s));
 const link=(kind,id,label)=>`<a href="${EXPLORER}/${kind}/${id}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
 function paint(){if(page==='monad')render();updateHeader();}
 function updateHeader(){const label=$('#wallet span:last-child');if(label)label.textContent=address?short(address):'连接钱包';}
 window.addEventListener('eip6963:announceProvider',event=>{const d=event.detail;if(d?.provider?.request&&d?.info?.uuid)wallets.set(d.info.uuid,d);});window.dispatchEvent(new Event('eip6963:requestProvider'));
 async function network(){if(!injected)throw Error('请先连接钱包');const id=await injected.request({method:'eth_chainId'});if(id.toLowerCase()!==HEX){try{await injected.request({method:'wallet_switchEthereumChain',params:[{chainId:HEX}]});}catch(e){if(Number(e.code)!==4902)throw e;await injected.request({method:'wallet_addEthereumChain',params:[{chainId:HEX,chainName:'Monad Testnet',nativeCurrency:{name:'Test MON',symbol:'MON',decimals:18},rpcUrls:[RPC],blockExplorerUrls:[EXPLORER]}]});await injected.request({method:'wallet_switchEthereumChain',params:[{chainId:HEX}]});}}if((await injected.request({method:'eth_chainId'})).toLowerCase()!==HEX)throw Error('请切换到 Monad Testnet；不会在主网发送交易');return new E.BrowserProvider(injected,'any',{cacheTimeout:-1});}
 async function signer(){const provider=await network();const s=await provider.getSigner();address=await s.getAddress();updateHeader();return s;}
 const accountChanged=()=>{epoch++;address='';snapshot=null;message='钱包账户或网络已变化，请刷新链上状态。';paint();};
 async function selectWallet(id){const next=wallets.get(id)?.provider||window.ethereum;if(!next?.request)throw Error('未检测到钱包。请用安装了 MetaMask、Rabby 或兼容钱包的浏览器打开本站；手机请在钱包内置浏览器打开。');if(injected?.removeListener){injected.removeListener('accountsChanged',accountChanged);injected.removeListener('chainChanged',accountChanged);}injected=next;injected.on?.('accountsChanged',accountChanged);injected.on?.('chainChanged',accountChanged);await injected.request({method:'eth_requestAccounts'});await signer();state.wallet=true;save();$('#social-dialog').close();await refresh();}
 function chooseWallet(){window.dispatchEvent(new Event('eip6963:requestProvider'));const entries=[...wallets.entries()];modal('连接你的测试网钱包',`<p class="modal-description">使用持有测试 MON 的钱包。后续交易均由钱包逐笔确认。</p>${entries.length?entries.map(([id,d])=>`<button class="outline full wallet-choice" data-wallet-provider="${esc(id)}">${esc(d.info.name)}</button>`).join(''):'<button class="primary full" data-wallet-provider="injected">连接浏览器钱包</button>'}<p class="form-note">手机请在钱包应用的内置浏览器打开本站。此版支持浏览器注入钱包，暂未接入 WalletConnect。</p><a class="text-button" href="https://campus-t-kolin-demo.lacyalbatross5.chatgpt.site/#monad" target="_blank" rel="noopener">在独立浏览器打开奖励页</a>`);}
 async function verifiedPool(target,provider=reader){if(!E.isAddress(target))throw Error('请输入有效奖励池地址');if(BigInt(await provider.send('eth_chainId',[]))!==BigInt(CHAIN))throw Error('RPC 未连接 Monad Testnet');const code=await provider.getCode(target);if(code.toLowerCase()!==A.runtime.toLowerCase())throw Error('该地址不是当前版本的 CampusT 测试网奖励池');return new E.Contract(target,A.abi,provider);}
 async function refresh(){const token=++epoch;message='正在读取 Monad 测试网…';paint();try{if(injected){const accounts=await injected.request({method:'eth_accounts'});address=accounts[0]?E.getAddress(accounts[0]):'';}let next=null;if(pool){const c=await verifiedPool(pool);const [owner,closed,paid,balance,eligible,claimed]=await Promise.all([c.owner(),c.closed(),c.paidCount(),reader.getBalance(pool),address?c.eligible(address):false,address?c.claimed(address):false]);next={owner,closed,paid,balance,eligible,claimed};}if(lastTx?.status==='pending'){const receipt=await reader.getTransactionReceipt(lastTx.hash);if(receipt){lastTx.status=receipt.status===1?'confirmed':'failed';if(lastTx.deploy&&receipt.status===1){pool=receipt.contractAddress;persist();}persist();}}if(token!==epoch)return;snapshot=next;if(next)persist();message=pool?'链上状态已更新':'连接钱包后创建奖励池，或导入品牌分享的奖励池地址。';}catch(e){if(token!==epoch)return;snapshot=null;message=errorMessage(e);}paint();}
 function errorMessage(e){if(e.code===4001||e.code==='ACTION_REJECTED')return '你取消了钱包操作，未完成交易。';if(e.code==='INSUFFICIENT_FUNDS')return '钱包测试 MON 不足，请为转账金额和 Gas 预留余额。';return e.reason||e.shortMessage||e.message||'操作失败，请重试';}
 async function transact(label,create,{deploy=false}={}){if(busy)return;if(lastTx?.status==='pending'){message='上一笔交易仍在确认中，请刷新状态或在钱包中查看，避免重复发送。';paint();return;}let confirmed=false,submitted=false;busy=true;message='请在钱包中确认：'+label;paint();try{const s=await signer();const tx=await create(s);submitted=true;lastTx={hash:tx.hash,status:'pending',label,deploy};persist();message='交易已提交，等待链上确认…';paint();let receipt;try{receipt=await tx.wait(1,120000);}catch(e){if(e.code==='TRANSACTION_REPLACED'&&!e.cancelled){receipt=e.receipt;lastTx.hash=e.replacement.hash;}else throw e;}if(!receipt||receipt.status!==1)throw Error('链上交易失败');lastTx.status='confirmed';confirmed=true;if(deploy)pool=receipt.contractAddress;persist();message=label+'已确认';}catch(e){if(submitted&&lastTx?.status==='pending'&&(e.receipt||e.code==='TRANSACTION_REPLACED')){lastTx.status='failed';persist();}message=errorMessage(e)+(lastTx?.status==='pending'?'；已提交的交易可点击「刷新状态」查询，勿重复发送。':'');}finally{busy=false;paint();if(confirmed)await refresh();}}
 async function contractFor(s){const c=await verifiedPool(pool,s.provider);return c.connect(s);}
 function view(){const own=address&&snapshot?.owner.toLowerCase()===address.toLowerCase();const available=snapshot&&!snapshot.closed&&snapshot.eligible&&!snapshot.claimed&&snapshot.balance>=1000000000000000n;return heading('每一份参与，真实到达钱包。','LUMA 校园摄影活动 · Monad 测试网奖励池')+`<div class="chain-banner"><span>MONAD TESTNET</span><strong>0.001 <small>测试 MON / 人</small></strong><p>品牌预存预算，确认领取资格；学生使用自己的钱包领取。</p></div><div class="chain-toolbar"><button class="primary" data-chain-connect>${address?short(address)+' · 切换钱包':'连接钱包'}</button><button class="outline" data-chain-refresh ${busy?'disabled':''}>刷新状态</button><span>仅测试网 · Chain ID 10143</span></div><div class="chain-message" role="status">${esc(message||'请先连接持有测试 MON 的钱包。')}</div>${lastTx?`<div class="chain-tx">${esc(lastTx.label)} · ${lastTx.status==='confirmed'?'链上已确认':lastTx.status==='failed'?'失败或已取消':'等待确认'} ${link('tx',lastTx.hash,'查看交易')}</div>`:''}<div class="chain-grid"><section class="panel"><h2>学生领取</h2><p class="muted">签退后，将你的钱包地址提供给品牌；品牌核实参与情况并授权后，即可领取。领取需要少量测试 MON 支付 Gas。</p><form id="pool-import"><label>活动奖励池地址<input name="pool" value="${esc(pool)}" placeholder="0x…" required autocomplete="off"></label><button class="outline full" type="submit" ${busy?'disabled':''}>导入并验证奖励池</button></form>${snapshot?`<dl class="chain-stats"><div><dt>奖励池余额</dt><dd>${fmt(snapshot.balance)} 测试 MON</dd></div><div><dt>已领取人数</dt><dd>${snapshot.paid.toString()}</dd></div><div><dt>当前钱包资格</dt><dd>${snapshot.claimed?'已领取':snapshot.closed?'奖励池已关闭':snapshot.eligible?'已授权，可领取':'等待品牌授权'}</dd></div></dl><p class="chain-address">品牌钱包：${link('address',snapshot.owner,short(snapshot.owner))}<br>奖励池：${link('address',pool,short(pool))}</p>`:''}<button class="primary full" data-chain-claim ${!available||!address||busy?'disabled':''}>${snapshot?.claimed?'此钱包已领取':'领取 0.001 测试 MON'}</button><button class="text-button" data-chain-copy-address ${!address?'disabled':''}>复制我的钱包地址给品牌</button>${pool?'<button class="text-button" data-chain-share>复制此奖励池的领取链接</button>':''}<p class="form-note">领取结果以链上状态为准。网站积分与头像框仍是本地演示奖励。</p></section><section class="panel"><h2>品牌管理</h2><p class="muted">通过钱包部署奖励池并预存测试 MON。每人固定 0.001；部署、授权和充值均需测试网 Gas。</p>${!pool?`<form id="pool-deploy"><label>首次预算（测试 MON）<input name="budget" type="text" inputmode="decimal" value="0.01" required></label><p class="form-note">默认 0.01 可供 10 人领取，可修改；不包含部署 Gas。</p><button class="primary full" type="submit" ${busy?'disabled':''}>部署并充值奖励池</button></form>`:own?`${!snapshot.closed?`<form id="pool-authorize"><label>已核实参与者的钱包地址<textarea name="recipients" rows="3" required placeholder="每行一个 0x 地址，最多 100 人"></textarea></label><label class="check-label"><input type="checkbox" name="verified" required>我已核实这些地址的活动参与资格</label><div class="chain-form-actions"><button class="primary" name="mode" value="allow" ${busy?'disabled':''}>授权自行领取</button><button class="outline" name="mode" value="revoke" ${busy?'disabled':''}>撤销未领取资格</button></div></form><form id="pool-fund"><label>追加预算（测试 MON）<input name="amount" type="text" inputmode="decimal" value="0.01" required></label><button class="outline full" ${busy?'disabled':''}>向奖励池充值</button></form><button class="text-button" data-chain-close ${busy?'disabled':''}>结束活动并关闭领取</button>`:`<p class="info-banner">奖励池已永久关闭，可以取回剩余测试 MON。</p><button class="outline full" data-chain-withdraw ${busy||snapshot.balance===0n?'disabled':''}>取回剩余预算</button>`}`:`<p class="info-banner">${snapshot?'当前钱包不是该奖励池的管理者。':'先验证奖励池地址，才能显示管理功能。'}</p>`}${pool?'<button class="text-button" data-chain-clear>清除本机选择，创建其他奖励池</button>':''}<p class="form-note">静态二维码不能证明真实到场，所以领取资格由品牌授权；不依据浏览器积分或签到记录直接放币。</p><a class="text-button" href="contracts/CampusRewardPool.sol" target="_blank" rel="noopener">查看测试网合约源码</a></section></div>`;}
 function amount(text){if(!/^(?:0|[1-9]\d*)(?:\.\d{1,18})?$/.test(text))throw Error('请输入最多 18 位小数的正数');const n=E.parseEther(text);if(n<=0n)throw Error('金额必须大于 0');return n;}
 function renderPage(){if(page!=='monad')return false;stopCamera();onsiteHeader('测试网奖励');$('#content').innerHTML=view();updateHeader();return true;}
 async function run(fn){try{await fn();}catch(e){message=errorMessage(e);paint();toast(message);if($('#social-dialog').open){let hint=$('#wallet-error');if(!hint){hint=document.createElement('p');hint.id='wallet-error';hint.className='form-note';hint.setAttribute('role','alert');$('#social-dialog').append(hint);}hint.textContent=message;}}}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(b.id==='wallet'||'chainConnect'in d)chooseWallet();if(d.walletProvider)run(()=>selectWallet(d.walletProvider));if('chainRefresh'in d)run(refresh);if('chainClaim'in d)run(()=>transact('领取 0.001 测试 MON',async s=>{const c=await contractFor(s);await c.claim.staticCall();return c.claim({chainId:CHAIN});}));if('chainWithdraw'in d)run(()=>transact('取回剩余测试 MON',async s=>(await contractFor(s)).withdraw({chainId:CHAIN})));if('chainClose'in d)modal('结束奖励发放',`<p class="modal-description">关闭后所有未领取的地址将无法领取，且不可重新开启。关闭后你可以取回剩余预算。</p><button class="primary full" data-chain-confirm-close>确认关闭并在钱包签名</button>`);if('chainConfirmClose'in d){$('#social-dialog').close();run(()=>transact('关闭奖励池',async s=>(await contractFor(s)).close({chainId:CHAIN})));}if('chainCopyAddress'in d)run(()=>navigator.clipboard.writeText(address).then(()=>toast('钱包地址已复制')));if('chainShare'in d)run(()=>navigator.clipboard.writeText(PUBLIC_ORIGIN+'/#monad?pool='+pool).then(()=>toast('领取链接已复制')));if('chainClear'in d&&!busy){pool='';snapshot=null;persist();paint();}});
 document.addEventListener('submit',e=>{const f=e.target;if(!['pool-import','pool-deploy','pool-authorize','pool-fund'].includes(f.id))return;e.preventDefault();if(busy)return;const fd=new FormData(f);run(async()=>{if(f.id==='pool-import'){const input=String(fd.get('pool')).trim();await verifiedPool(input);pool=E.getAddress(input);snapshot=null;persist();await refresh();}if(f.id==='pool-deploy'){const budget=amount(String(fd.get('budget')).trim());if(budget<1000000000000000n)throw Error('预算至少 0.001 测试 MON');await transact('部署并充值奖励池',async s=>{const c=await new E.ContractFactory(A.abi,A.bytecode,s).deploy({value:budget,chainId:CHAIN});return c.deploymentTransaction();},{deploy:true});}if(f.id==='pool-authorize'){if(!fd.has('verified'))throw Error('请先确认活动资格');const list=[...new Set(String(fd.get('recipients')).split(/[\s,;，；]+/).filter(Boolean))];if(!list.length||list.length>100||list.some(a=>!E.isAddress(a)||a===E.ZeroAddress))throw Error('请填写 1 至 100 个有效钱包地址');const allow=e.submitter?.value!=='revoke';await transact(allow?'授权参与者领取':'撤销领取资格',async s=>(await contractFor(s)).setEligible(list.map(a=>E.getAddress(a)),allow,{chainId:CHAIN}));}if(f.id==='pool-fund'){const value=amount(String(fd.get('amount')).trim());await transact('追加奖励预算',async s=>(await contractFor(s)).fund({value,chainId:CHAIN}));}});});
 function route(){if(!location.hash.startsWith('#monad'))return;const match=location.hash.match(/^#monad(?:\?pool=(0x[0-9a-fA-F]{40}))?$/);if(!match)return;page='monad';if(match[1]){try{pool=E.getAddress(match[1]);snapshot=null;}catch{message='分享链接中的地址校验失败，请核对品牌提供的地址。';paint();return;}}paint();run(refresh);}
 window.addEventListener('hashchange',route);
 return {renderPage,updateHeader,route,refresh,chooseWallet};
})();
render();routeAttendance();monad.route();monad.updateHeader();
